<?php namespace App\Http\Controllers; use App\Models\{Customer,Expense,Material,Purchase,Sale,StockMovement,Supplier}; class DashboardController { public function index(){ $today=today();$purchases=Purchase::whereDate('purchased_at',$today)->sum('grand_total');$sales=Sale::whereDate('sold_at',$today)->sum('grand_total');$expenses=Expense::whereDate('expense_date',$today)->sum('amount');$cogs=Sale::whereDate('sold_at',$today)->sum('cost_of_goods'); return view('dashboard.index',compact('purchases','sales','expenses','cogs'))->with(['stockValue'=>Material::selectRaw('SUM(current_stock * average_cost) value')->value('value')??0,'customers'=>Customer::count(),'suppliers'=>Supplier::count(),'transactions'=>Purchase::count()+Sale::count(),'recentMovements'=>StockMovement::with('material')->latest('moved_at')->take(8)->get()]);} }
